/**
 * One reconciliation pass over every node's utilization vs the OPEN NodeAlert
 * rows. Safe to call every monitor cadence.
 */
export async function nodeCapacitySweep(): Promise<void> {
  if (SANDBOX) return; // no real nodes to size in the sandbox

  const t = await nodeThresholds();

  let utils: NodeUtil[];
  try {
    const [proxmox, hosting] = await Promise.all([proxmoxNodeUtil(t), hostingNodeUtil(t)]);
    utils = [...proxmox, ...hosting];
  } catch (e) {
    console.error("[node-capacity] utilization compute error", e);
    return;
  }

  let open: Array<{
    id: string;
    nodeKind: string;
    nodeId: string;
    dimension: string;
    severity: string;
    lastNotifiedAt: Date | null;
  }>;
  try {
    open = await db.nodeAlert.findMany({
      where: { status: "OPEN" },
      select: { id: true, nodeKind: true, nodeId: true, dimension: true, severity: true, lastNotifiedAt: true },
    });
  } catch (e) {
    console.error("[node-capacity] could not read open alerts", e);
    return;
  }
  const openByKey = new Map(open.map((a) => [`${a.nodeKind}:${a.nodeId}:${a.dimension}`, a]));

  const now = new Date();
  const cooldownMs = NODE_CAP_COOLDOWN_HOURS * 60 * 60_000;
  const floor = resolveFloor(t);
  // Every (kind,id,dimension) we actually evaluated this sweep — so a dimension
  // that was merely ABSENT (e.g. Proxmox unreachable, so no CPU/DISK reading) is
  // never mistaken for "recovered".
  const evaluated = new Set<string>();
  const nodeIds = new Set(utils.map((u) => `${u.kind}:${u.id}`));

  for (const nu of utils) {
    for (const d of nu.dims) {
      const key = `${nu.kind}:${nu.id}:${d.dimension}`;
      evaluated.add(key);
      const sev = severityFor(d.pct, t);
      const existing = openByKey.get(key);
      const roundedPct = Math.round(d.pct);
      const metric = {
        allocPct: d.allocPct === null ? null : Math.round(d.allocPct),
        realPct: d.realPct === null ? null : Math.round(d.realPct),
        warnPct: t.warnPct,
        critPct: t.critPct,
      };

      if (sev === "OK") {
        // Auto-resolve, but only once we've dropped a hysteresis margin below WARN.
        if (existing && d.pct < floor) {
          try {
            await db.nodeAlert.update({
              where: { id: existing.id },
              data: { status: "RESOLVED", pct: roundedPct, detail: d.detail, resolvedAt: now },
            });
            await notifyNodeCapacity(
              `Node capacity cleared: ${nu.name} — ${d.dimension}`,
              `${nu.kind === "PROXMOX" ? "Compute node" : "Hosting node"} "${nu.name}" ${d.dimension} ` +
                `is back to ${roundedPct}% (below the ${t.warnPct}% warn line). Capacity warning resolved.`,
            );
          } catch (e) {
            console.error(`[node-capacity] resolve failed for ${key}`, e);
          }
        }
        // Between the floor and WARN: leave the alert OPEN (hysteresis) — no-op.
        continue;
      }

      // sev is WARN or CRITICAL.
      try {
        if (!existing) {
          // NEW — always notify.
          await db.nodeAlert.create({
            data: {
              nodeKind: nu.kind,
              nodeId: nu.id,
              nodeName: nu.name,
              dimension: d.dimension,
              severity: sev,
              pct: roundedPct,
              detail: d.detail,
              metric,
              status: "OPEN",
              lastNotifiedAt: now,
            },
          });
          await notifyNodeCapacity(
            `Node capacity ${sev}: ${nu.name} — ${d.dimension}`,
            dimBody(nu, d, sev, t.warnPct, t.critPct),
          );
        } else if (
          existing.severity !== sev &&
          isGenuineSeverityChange(existing.severity as CapSeverity, sev, d.pct, t.critPct, NODE_CAP_RESOLVE_MARGIN)
        ) {
          // Genuine escalation (WARN -> CRITICAL, always worth an immediate
          // notify) or a de-escalation (CRITICAL -> WARN) that has cleared the
          // SAME hysteresis margin the WARN -> OK resolution above already
          // uses — always notify.
          await db.nodeAlert.update({
            where: { id: existing.id },
            data: { severity: sev, pct: roundedPct, detail: d.detail, metric, lastNotifiedAt: now },
          });
          await notifyNodeCapacity(
            `Node capacity ${sev}: ${nu.name} — ${d.dimension}`,
            dimBody(nu, d, sev, t.warnPct, t.critPct),
          );
        } else if (existing.severity !== sev) {
          // De-escalation (CRITICAL -> WARN) that has NOT yet cleared the
          // hysteresis margin below critPct — a metric sitting right on the
          // CRITICAL line bounces WARN/CRITICAL every sweep, and without this
          // branch every single bounce re-notified regardless of the cooldown
          // (found live 2026-09-25: "primary" RAM sat within ~1% of critPct
          // and flapped WARN/CRITICAL every 30-90 minutes all day, each flip
          // bypassing NODE_CAP_COOLDOWN_HOURS entirely — reports@nxeon.cloud
          // was sending 30-80 "Node capacity" emails/day as a result). Treat
          // this exactly like "same severity persists" below: keep the
          // stored severity at its worse value, refresh the figure, and only
          // re-notify once the ordinary cooldown has elapsed.
          const due = !existing.lastNotifiedAt || now.getTime() - existing.lastNotifiedAt.getTime() > cooldownMs;
          await db.nodeAlert.update({
            where: { id: existing.id },
            data: { pct: roundedPct, detail: d.detail, metric, ...(due ? { lastNotifiedAt: now } : {}) },
          });
          if (due) {
            await notifyNodeCapacity(
              `Node capacity ${existing.severity}: ${nu.name} — ${d.dimension}`,
              dimBody(nu, d, existing.severity as CapSeverity, t.warnPct, t.critPct),
            );
          }
        } else {
          // SAME severity persists — refresh the figure silently, re-notify only
          // once the cooldown has elapsed.
          const due = !existing.lastNotifiedAt || now.getTime() - existing.lastNotifiedAt.getTime() > cooldownMs;
          await db.nodeAlert.update({
            where: { id: existing.id },
            data: { pct: roundedPct, detail: d.detail, metric, ...(due ? { lastNotifiedAt: now } : {}) },
          });
          if (due) {
            await notifyNodeCapacity(
              `Node capacity ${sev}: ${nu.name} — ${d.dimension}`,
              dimBody(nu, d, sev, t.warnPct, t.critPct),
            );
          }
        }
      } catch (e) {
        console.error(`[node-capacity] alert upsert failed for ${key}`, e);
      }
    }
  }

  // Close out alerts whose NODE no longer exists at all (deleted / de-registered).
  // A dimension that was merely absent this sweep (unreachable Proxmox) is left
  // untouched above — we only resolve here when the whole node is gone.
  for (const [key, a] of openByKey) {
    if (evaluated.has(key)) continue;
    if (nodeIds.has(`${a.nodeKind}:${a.nodeId}`)) continue; // node still exists, dim just unobserved
    try {
      await db.nodeAlert.update({
        where: { id: a.id },
        data: { status: "RESOLVED", resolvedAt: now, detail: "Node removed — capacity alert closed." },
      });
    } catch (e) {
      console.error(`[node-capacity] stale-node resolve failed for ${key}`, e);
    }
  }
}

