/**

/**
 * Debounced, auto-resolving admin alerts for the fleet sweeps (IP clashes,
 * running/IP-sharing leftover VMs, unknown VM ids). Reuses the NodeAlert table
 * and the in-app admin notification path the node-capacity sweep uses
 * (worker/monitor.ts notifyAdmins) — no new alert machinery.
 *
 * One OPEN NodeAlert per condition, keyed (nodeKind=PROXMOX, nodeId, dimension)
 * where dimension is `IP-CLASH:<ip>`, `LEFTOVER-VM:<vmid>` or `UNKNOWN-VMID:<vmid>`.
 *   - new condition            -> create + notify
 *   - WARN -> CRITICAL         -> update + notify (escalation only)
 *   - persists, same severity  -> refresh detail silently; re-notify once per cooldown
 *   - gone, node read OK       -> RESOLVED + "cleared" notify
 *   - node not read this sweep -> left untouched (absent evidence is not recovery)
 * Pure planning in `planFleetAlerts` (tested); `applyFleetAlerts` does the I/O.
 */
import { db } from "../lib/db";
import { FLEET_ALERT_PREFIXES, type AlertOp, type OpenAlert } from "../lib/fleet-alert-plan";
import { notifyAdmins } from "./monitor";

export async function applyFleetAlerts(ops: readonly AlertOp[], now = new Date()): Promise<void> {
  for (const o of ops) {
    try {
      if (o.op === "create") {
        await db.nodeAlert.create({
          data: { nodeKind: "PROXMOX", nodeId: o.desired.nodeId, nodeName: o.desired.nodeName, dimension: o.desired.dimension, severity: o.desired.severity, pct: 0, detail: o.desired.detail, status: "OPEN", lastNotifiedAt: now },
        });
        await notifyAdmins(o.notify.title, o.notify.body, "/admin/nodes");
      } else if (o.op === "update") {
        await db.nodeAlert.update({
          where: { id: o.id },
          data: { severity: o.desired.severity, detail: o.desired.detail, ...(o.notifyNow ? { lastNotifiedAt: now } : {}) },
        });
        if (o.notifyNow && o.notify) await notifyAdmins(o.notify.title, o.notify.body, "/admin/nodes");
      } else {
        await db.nodeAlert.update({ where: { id: o.id }, data: { status: "RESOLVED", resolvedAt: now } });
        await notifyAdmins(o.notify.title, o.notify.body, "/admin/nodes");
      }
    } catch (e) {
      console.error("[fleet-alerts] apply failed", o.op, (o as any).id ?? (o as any).desired?.dimension, e);
    }
  }
}

export async function openFleetAlerts(): Promise<OpenAlert[]> {
  const rows = await db.nodeAlert.findMany({
    where: { status: "OPEN", nodeKind: "PROXMOX", OR: FLEET_ALERT_PREFIXES.map((p) => ({ dimension: { startsWith: p } })) },
    select: { id: true, nodeId: true, dimension: true, severity: true, lastNotifiedAt: true },
  });
  return rows;
}
