/**
 * Pure planning for debounced, auto-resolving fleet alerts (see worker/fleet-alerts.ts). No I/O.
 */

export const FLEET_ALERT_PREFIXES = ["IP-CLASH:", "LEFTOVER-VM:", "UNKNOWN-VMID:", "OFFSITE-BACKUP:"] as const;
export const FLEET_ALERT_COOLDOWN_HOURS = Number(process.env.NXEON_FLEET_ALERT_COOLDOWN_HOURS ?? 24);

export type DesiredAlert = { nodeId: string; nodeName: string; dimension: string; severity: "WARN" | "CRITICAL"; title: string; detail: string };
export type OpenAlert = { id: string; nodeId: string; dimension: string; severity: string; lastNotifiedAt: Date | null };
export type AlertOp =
  | { op: "create"; desired: DesiredAlert; notify: { title: string; body: string } }
  | { op: "update"; id: string; desired: DesiredAlert; notifyNow: boolean; notify?: { title: string; body: string } }
  | { op: "resolve"; id: string; nodeName: string; dimension: string; notify: { title: string; body: string } };

export function isFleetDimension(d: string): boolean {
  return FLEET_ALERT_PREFIXES.some((p) => d.startsWith(p));
}

export function planFleetAlerts(opts: {
  desired: readonly DesiredAlert[];
  open: readonly OpenAlert[];
  /** Nodes whose inventory was read successfully this sweep (only these may resolve). */
  readNodeIds: ReadonlySet<string>;
  nodeNames: ReadonlyMap<string, string>;
  now: Date;
  cooldownMs?: number;
}): AlertOp[] {
  const cooldownMs = opts.cooldownMs ?? FLEET_ALERT_COOLDOWN_HOURS * 3_600_000;
  const key = (nodeId: string, dim: string) => `${nodeId}|${dim}`;
  const openBy = new Map(opts.open.filter((a) => isFleetDimension(a.dimension)).map((a) => [key(a.nodeId, a.dimension), a]));
  const out: AlertOp[] = [];
  const seen = new Set<string>();
  for (const d of opts.desired) {
    const k = key(d.nodeId, d.dimension);
    seen.add(k);
    const ex = openBy.get(k);
    if (!ex) {
      out.push({ op: "create", desired: d, notify: { title: d.title, body: d.detail } });
    } else if (ex.severity !== d.severity && d.severity === "CRITICAL") {
      out.push({ op: "update", id: ex.id, desired: d, notifyNow: true, notify: { title: d.title, body: d.detail } });
    } else {
      // Keep the worse stored severity on a de-escalation; refresh text silently.
      const due = !ex.lastNotifiedAt || opts.now.getTime() - ex.lastNotifiedAt.getTime() > cooldownMs;
      const keepSev = ex.severity === "CRITICAL" ? "CRITICAL" : d.severity;
      const dd = { ...d, severity: keepSev as "WARN" | "CRITICAL" };
      out.push({ op: "update", id: ex.id, desired: dd, notifyNow: due, ...(due ? { notify: { title: dd.title, body: dd.detail } } : {}) });
    }
  }
  for (const [k, a] of openBy) {
    if (seen.has(k) || !opts.readNodeIds.has(a.nodeId)) continue;
    const nodeName = opts.nodeNames.get(a.nodeId) ?? a.nodeId;
    out.push({
      op: "resolve", id: a.id, nodeName, dimension: a.dimension,
      notify: { title: `Fleet alert cleared: ${nodeName} — ${a.dimension}`, body: `${a.dimension} on ${nodeName} is no longer present. Alert resolved.` },
    });
  }
  return out;
}

/**
 * Fleet-wide private-IP audit — REPORT ONLY. Never changes a VM, a config, a
 * NAT rule or a Server row.
 *
 * For every enabled node: read every VM/CT config (and the ARP table where the
 * node-agent supports it) and report
 *   - duplicate IPs: one address configured on 2+ VMs/CTs (2026-10-02: node-2
 *     had 10.20.1.101 on VMs 101, 137, 138 and 644, and a duplicated .106),
 *   - DB drift: a Server row whose ipAddress is not what its own VM's config
 *     says, or whose address is configured on a DIFFERENT VM.
 * The worker runs it at start-up and every 6 h (registerSweeps); the same code
 * backs scripts/fleet-ip-audit.ts for an on-demand read-only run.
 */
import { db } from "../lib/db";
import { pveFor } from "../lib/proxmox";
import { agentNeighbors } from "../lib/node-agent";
import { logError } from "../lib/log";
import { nodeIpInventory, localNeighbors } from "../lib/node-ip-inventory";
import { duplicatePrivateIps, type VmIpEntry } from "../lib/provision-guard";
import { MOVED_SOURCE_TAG } from "../lib/vm-move/plan";
import { planFleetAlerts, type DesiredAlert } from "../lib/fleet-alert-plan";
import { applyFleetAlerts, openFleetAlerts } from "./fleet-alerts";
import { unknownVmids, highestCountableVmid, type ObservedVm } from "../lib/vmid-guard";
import { loadUsedVmids, recordVmidsUsed, bumpVmidHighWater, VMID_BASELINE_KEY } from "../lib/vmid-high-water";

/** Days a moved source is kept before it is safe to delete (mirrors VM_MOVE_KEEP_SOURCE_DAYS). */
const LEFTOVER_KEEP_DAYS = Math.max(1, Number(process.env.VM_MOVE_KEEP_SOURCE_DAYS ?? 7));

export type NodeIpAuditFinding =
  | { kind: "duplicate"; node: string; ip: string; vmids: number[]; servers: { vmid: number; hostname: string | null }[] }
  | { kind: "drift"; node: string; serverId: string; hostname: string; vmid: number; dbIp: string; vmIps: string[] }
  | { kind: "held-by-other-vm"; node: string; serverId: string; hostname: string; vmid: number; dbIp: string; otherVmids: number[] }
  | {
      /** A source VM a move left behind (tag `nxeon-moved`, or a DONE VmMove not yet cleaned) with no Server row of its own. NEVER auto-deleted. */
      kind: "leftover"; node: string; vmid: number; name: string | null; running: boolean; tagged: boolean;
      ips: string[]; sharesIpWith: number[]; keepUntil: string | null;
    }
  | { kind: "unknown-vmid"; node: string; vmid: number; name: string | null }
  | { kind: "unreadable"; node: string; error: string };

export type MoveLeftoverRef = { sourceVmid: number; keepSourceUntil: Date | null };

/** Pure: findings for one node from its inventory + the DB rows that live there. */
export function auditNodeIps(
  node: string,
  entries: readonly VmIpEntry[],
  servers: readonly { id: string; hostname: string; vmid: number | null; ipAddress: string | null }[],
  moves: readonly MoveLeftoverRef[] = []
): NodeIpAuditFinding[] {
  const out: NodeIpAuditFinding[] = [];
  const byVmid = new Map(servers.filter((s) => s.vmid != null).map((s) => [s.vmid as number, s]));
  for (const [ip, vmids] of duplicatePrivateIps(entries)) {
    out.push({ kind: "duplicate", node, ip, vmids, servers: vmids.map((v) => ({ vmid: v, hostname: byVmid.get(v)?.hostname ?? null })) });
  }
  const entryByVmid = new Map(entries.map((e) => [e.vmid, e]));
  for (const s of servers) {
    if (s.vmid == null || !s.ipAddress) continue;
    const own = entryByVmid.get(s.vmid);
    const others = entries.filter((e) => e.vmid !== s.vmid && e.ips.includes(s.ipAddress!)).map((e) => e.vmid);
    if (others.length) out.push({ kind: "held-by-other-vm", node, serverId: s.id, hostname: s.hostname, vmid: s.vmid, dbIp: s.ipAddress, otherVmids: others });
    unknown = await reconcileVmids(observed);
  } catch (e) {
    console.error("[vmid] reconcile failed", e);
  }
  for (const u of unknown) findings.push({ kind: "unknown-vmid", node: u.nodeName, vmid: u.vmid, name: u.name ?? null });

  for (const f of findings) {
    const line = describeFinding(f);
    const quiet = f.kind === "leftover" && !f.running && !f.sharesIpWith.length; // report-only: safe to delete later
    if (quiet) { console.log(`[ip-audit] ${line}`); continue; }
    console.error(`[ip-audit] ${line}`);
    if (f.kind !== "unreadable") logError("fleet.ip-audit", new Error(line), { source: "sweep", kind: f.kind, node: f.node });
  }
  if (!findings.length) console.log("[ip-audit] no duplicate or drifted private IPs on any node");

  try {
    const desired: DesiredAlert[] = [];
    for (const n of readNodes) desired.push(...desiredIpAlerts(n, findings));
    for (const u of unknown) {
      desired.push({
        nodeId: u.nodeId, nodeName: u.nodeName, dimension: `UNKNOWN-VMID:${u.vmid}`, severity: "WARN",
        title: `Unknown VM id: ${u.nodeName} — VM ${u.vmid}`,
        detail: `VM ${u.vmid}${u.name ? ` (${u.name})` : ""} exists on ${u.nodeName} with an id the platform never assigned (no Server row, no move, not in the retired-id record). Built by hand? Acknowledge with: npx tsx scripts/vmid-ack.ts ${u.vmid}`,
      });
    }
    const ops = planFleetAlerts({
      desired,
      open: await openFleetAlerts(),
      readNodeIds: new Set(readNodes.map((n) => n.id)),
      nodeNames: new Map(readNodes.map((n) => [n.id, n.name])),
      now: new Date(),
    });
    await applyFleetAlerts(ops);
  } catch (e) {
    console.error("[ip-audit] alert reconcile failed", e);
  }
}
