/**
 * Off-site backup FRESHNESS sweep (hourly). Default OFF: set NXEON_OFFSITE_FRESHNESS=1.
 *
 * Reads (never writes to a node or the remote): each node-agent's /v1/backup/health, the primary's own state,
 * `systemctl show nxeon-backup-offsite.timer`, the remote listing (rclone lsjson) and the uploader/restore-test
 * status files; evaluates them with lib/backup-freshness.ts; raises debounced, auto-resolving alerts through
 * lib/fleet-alert-plan.ts (dimension prefix OFFSITE-BACKUP:); and writes the inventory the admin page shows to
 * /tank/backup/status/offsite-inventory.json. The page marks that file stale after 12 h, so a dead checker is visible.
 */
import { execFile } from "node:child_process";
import { promises as fs } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { planFleetAlerts } from "../lib/fleet-alert-plan";
import { OFFSITE_ROOT_DEFAULT } from "../lib/backup-layout";
import { listRemote, remoteAbout } from "../lib/backup-stream";
import { collectLocalHealth, toNodeHealth, unreachable, type AgentBackupHealth } from "../lib/backup-node-health";
import { newestFromRemote, runSweep } from "../lib/backup-sweep-plan";
import type { NodeHealth, OffsiteState } from "../lib/backup-freshness";
import { agentBackupHealth } from "../lib/node-agent";
import { applyFleetAlerts, openFleetAlerts } from "./fleet-alerts";

const execFileP = promisify(execFile);
const STATUS_DIR = process.env.NXEON_BACKUP_STATUS_DIR || "/tank/backup/status";
const REMOTE = process.env.OFFSITE_RCLONE_REMOTE || `dropbox:${OFFSITE_ROOT_DEFAULT}`;
const PRIMARY_NAME = process.env.NXEON_PRIMARY_NODE_NAME || "primary";

async function readJson(f: string): Promise<any | null> {
  try { return JSON.parse(await fs.readFile(path.join(STATUS_DIR, f), "utf8")); } catch { return null; }
}

async function offsiteTimer(): Promise<{ enabled: boolean | null; active: boolean | null }> {
  try {
    const { stdout } = await execFileP("systemctl", ["show", "nxeon-backup-offsite.timer", "-p", "LoadState,UnitFileState,ActiveState"], { timeout: 8000 });
    const kv = Object.fromEntries(stdout.trim().split("\n").map((l) => l.split("=", 2) as [string, string]));
    if (kv.LoadState === "not-found") return { enabled: false, active: false };
    return { enabled: ["enabled", "enabled-runtime", "static"].includes(kv.UnitFileState), active: kv.ActiveState === "active" };
  } catch { return { enabled: null, active: null }; }
}

export async function offsiteBackupSweep(): Promise<void> {
  if (process.env.NXEON_OFFSITE_FRESHNESS !== "1" || SANDBOX) return;
  const now = Date.now();
  const nodes = await db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, isPrimary: true, publicIp: true, agentPort: true, agentTokenEnc: true } });
  const health: NodeHealth[] = [];
  for (const n of nodes) {
    try {
      const h: AgentBackupHealth = n.isPrimary ? await collectLocalHealth() : ((await agentBackupHealth(n)) as AgentBackupHealth);
      if (!h.vmsOk && !n.isPrimary) throw new Error("guest list unreadable on the node");
      health.push(toNodeHealth(h, n.isPrimary ? PRIMARY_NAME : n.name, n.id));
    } catch (e: any) {
      health.push(unreachable(n.isPrimary ? PRIMARY_NAME : n.name, n.id, String(e?.message ?? e)));
    }
  }

  let offsite: OffsiteState;
  const [timer, up] = [await offsiteTimer(), await readJson("offsite.json")];
  try {
    const files = await listRemote(REMOTE);
    const about = await remoteAbout(REMOTE);
    offsite = { read: true, newest: newestFromRemote(files), usedBytes: about.used, totalBytes: about.total, timerEnabled: timer.enabled, timerActive: timer.active, lastUploadOkMs: up?.lastSuccessAt ? Date.parse(up.lastSuccessAt) : null, encrypted: typeof up?.encrypted === "boolean" ? up.encrypted : null };
  } catch (e: any) {
    offsite = { read: false, error: String(e?.message ?? e), newest: {}, usedBytes: null, totalBytes: null, timerEnabled: timer.enabled, timerActive: timer.active, lastUploadOkMs: null, encrypted: null };
  }
  const rt = await readJson("restore-test.json");
  const restoreTest = rt ? { lastMs: rt.lastSuccessAt ? Date.parse(rt.lastSuccessAt) : null, lastOk: typeof rt.ok === "boolean" ? rt.ok : null } : null;

  const r = runSweep({ now, primaryNode: PRIMARY_NAME, nodes: health, offsite, restoreTest });
  try {
    await applyFleetAlerts(planFleetAlerts({ desired: r.desired, open: await openFleetAlerts(), readNodeIds: r.readNodeIds, nodeNames: r.nodeNames, now: new Date(now) }));
  } catch (e) { console.error("[offsite-backup] alert reconcile failed", e); }

  try {
    const body = { generatedAt: now, headline: r.headline, findings: r.findings, offsite: { read: offsite.read, error: offsite.error ?? null, usedBytes: offsite.usedBytes, totalBytes: offsite.totalBytes, timerEnabled: offsite.timerEnabled, timerActive: offsite.timerActive, lastUploadOkMs: offsite.lastUploadOkMs, encrypted: offsite.encrypted, newest: offsite.newest }, nodes: health.map((n) => ({ node: n.node, reachable: n.reachable, error: n.error ?? null, timers: n.timers, hypervisorNewestMs: n.hypervisorNewestMs, backupFs: n.backupFs, vms: n.vms })) };
    await fs.writeFile(path.join(STATUS_DIR, "offsite-inventory.json.tmp"), JSON.stringify(body));
    await fs.rename(path.join(STATUS_DIR, "offsite-inventory.json.tmp"), path.join(STATUS_DIR, "offsite-inventory.json"));
    await fs.chmod(path.join(STATUS_DIR, "offsite-inventory.json"), 0o644);
  } catch (e) { console.error("[offsite-backup] could not write inventory", e); }
}
 *
 * Each entry used to be an inline `if (Date.now() - lastX > interval)` block
 * at the top of the claim loop; intervals and groupings are preserved exactly
 * (a group that ran as one block with ordering requirements — e.g. partner
 * commissions AFTER the renewal sweeps — stays one sweep fn). Per-sweep
 * `timeoutMs` is the budget after which the runner stops waiting and logs an
 * overrun; see the runner's doc comment for why that is not a cancel.
 *
 * Exported for the load-test harness, which registers nothing but still
 * needs the list to document what else competes for the process.
 */
export function registerSweeps(runner: SweepRunner): void {
  const m = 60_000;
  const h = 60 * m;
  const add = (name: string, intervalMs: number, fn: () => Promise<unknown>, timeoutMs?: number) =>
    runner.register({ name, intervalMs, fn, timeoutMs });

  // Backstop for the first-month-free card/Stripe HOLD (lib/promo-redemption.ts)
