/**
 * READ-ONLY inspection of OVH's two per-IP upstream filters:
 *
 *  1. the GAME firewall   `/ip/{ip}/game/{ip}` (+ `/rule`)   — field `firewallModeEnabled`
 *  2. the NETWORK firewall `/ip/{ip}/firewall[/{ip}]`        — field `enabled`
 *
 * Why this exists (2026-10-04): node-4's game firewall was in STRICT mode with a
 * single stale rule (`other:20055-20055`). In strict mode OVH drops every UDP
 * port that no rule allows, at the provider edge, so every UDP game on the node
 * was unreachable from the internet while the primary's own probes still worked
 * and the servers looked healthy. Nothing in the platform looked at it.
 *
 * HARD RULE: this module only ever issues HTTP GET. There is no helper here (and
 * there must never be one) that changes a mode or a rule — turning strict mode
 * off is a production change that needs explicit owner approval.
 *
 * Layout: pure parsing + verdicts (no I/O, unit-tested with fixtures in
 * test/ovh-game-firewall.test.ts), a thin GET-only HTTP layer that takes an
 * injectable getter, and `listGameFirewallForNode` for the DB-backed IP list.
 */
import { ovh, OvhHttpError, ovhConfigured } from "./ovh";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type GameRule = {
  id: number | string;
  protocol: string | null;
  portFrom: number | null;
  portTo: number | null;
  /** OVH game rules carry no action (they are allow-rules); null unless OVH ever returns one. */
  action: string | null;
  state: string | null;
};

export type GameFirewall = {
  ip: string;
  /** false = OVH has no game object for this IP, i.e. no game firewall is enforced. */
  exists: boolean;
  firewallModeEnabled: boolean | null;
  /** OVH state: ok | firewallModeDisablePending | firewallModeEnablePending | ... */
  state: string | null;
  maxRules: number | null;
  rules: GameRule[];
};

export type NetworkFirewallRule = {
  id: number | string;
  sequence: number | null;
  action: string | null; // permit | deny
  protocol: string | null;
  source: string | null;
  destinationPort: string | null;
  state: string | null;
};

export type NetworkFirewall = {
  ip: string;
  /** false = the IP is not on OVH's network firewall at all. */
  exists: boolean;
  enabled: boolean | null;
  state: string | null;
  rules: NetworkFirewallRule[];
};

export type Level = "PASS" | "WARN" | "FAIL";
export type Verdict = { level: Level; summary: string; remediation?: string };

export type IpFirewallReport =
  | {
      ip: string;
      ok: true;
      game: GameFirewall;
      network: NetworkFirewall;
      gameVerdict: Verdict;
      networkVerdict: Verdict;
    }
  | { ip: string; ok: false; error: string };

// ---------------------------------------------------------------------------
// Pure parsing
// ---------------------------------------------------------------------------

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
const str = (v: unknown): string | null => (typeof v === "string" ? v : null);

/**
 * `gameBody` = GET /ip/{ip}/game/{ip}; `ruleBodies` = GET .../rule/{id} for each id.
 * Pass `gameBody = null` for a 404 (no game object).
 */
export function parseGameFirewall(ip: string, gameBody: any | null, ruleBodies: readonly any[] = []): GameFirewall {
  if (!gameBody || typeof gameBody !== "object") {
    return { ip, exists: false, firewallModeEnabled: null, state: null, maxRules: null, rules: [] };
  }
  return {
    ip,
    exists: true,
    firewallModeEnabled: typeof gameBody.firewallModeEnabled === "boolean" ? gameBody.firewallModeEnabled : null,
    state: str(gameBody.state),
    maxRules: num(gameBody.maxRules),
    rules: ruleBodies
      .filter((r) => r && typeof r === "object")
      .map((r) => ({
        id: r.id ?? "?",
        protocol: str(r.protocol),
        portFrom: num(r.ports?.from),
        portTo: num(r.ports?.to),
        action: str(r.action),
        state: str(r.state),
      })),
  };
}

/** `listBody` = GET /ip/{ip}/firewall (array of IPs on the firewall); `detail` = GET /ip/{ip}/firewall/{ip}. */
export function parseNetworkFirewall(
  ip: string,
  listBody: unknown,
  detail: any | null,
  ruleBodies: readonly any[] = []
): NetworkFirewall {
  const onFirewall = Array.isArray(listBody) && listBody.includes(ip);
  if (!onFirewall || !detail || typeof detail !== "object") {
    return { ip, exists: false, enabled: null, state: null, rules: [] };
  }
  return {
    ip,
    exists: true,
    enabled: typeof detail.enabled === "boolean" ? detail.enabled : null,
    state: str(detail.state),
    rules: ruleBodies
      .filter((r) => r && typeof r === "object")
      .map((r) => ({
        id: r.sequence ?? r.id ?? "?",
        sequence: num(r.sequence),
        action: str(r.action),
        protocol: str(r.protocol),
        source: str(r.source),
        destinationPort: str(r.destinationPort),
        state: str(r.state),
      })),
  };
}

export function describeGameRule(r: GameRule): string {
  const ports = r.portFrom === null ? "?" : r.portTo === null || r.portTo === r.portFrom ? `${r.portFrom}` : `${r.portFrom}-${r.portTo}`;
  return `${r.protocol ?? "?"}:${ports}${r.action ? ` (${r.action})` : ""}`;
}

// ---------------------------------------------------------------------------
// Pure verdicts
// ---------------------------------------------------------------------------

/** Exact operator remediation for a strict-mode game firewall. Plain ASCII on purpose (goes to logs, mail, shell). */
export function strictModeRemediation(ip: string): string {
  const e = encodeURIComponent(ip);
  return (
    `OVH game firewall STRICT MODE is ON for ${ip}: OVH drops every UDP port not allowed by a rule, at the provider edge, ` +
    `so UDP game servers on this IP are unreachable from the internet while the host and its own probes look healthy. ` +
    `Look at: OVH manager > Bare Metal Cloud > IP > ${ip} > "..." > Game firewall (or read-only API: GET /ip/${e}/game/${e} and GET /ip/${e}/game/${e}/rule). ` +
    `Fix = either turn strict mode OFF (PUT /ip/${e}/game/${e} {"firewallModeEnabled":false}; OVH goes firewallModeDisablePending -> ok in ~1 minute) ` +
    `or add an allow-rule for every UDP port in use. Turning it off changes production traffic filtering and REQUIRES OWNER APPROVAL - do not change it unasked. ` +
    `Re-run scripts/verify-node.sh and probe a UDP game from two other nodes (scripts/udp-reach-probe.sh) afterwards.`
  );
}

export function gameFirewallVerdict(g: GameFirewall): Verdict {
  if (!g.exists) {
    return { level: "PASS", summary: `${g.ip}: no OVH game firewall object (not enforced)` };
  }
  const state = g.state ?? "unknown";
  const rules = g.rules.length ? `${g.rules.length} rule(s): ${g.rules.map(describeGameRule).join(", ")}` : "no rules";
  const stateLc = state.toLowerCase();
  if (g.firewallModeEnabled === true) {
    if (stateLc.includes("disablepending")) {
      return { level: "WARN", summary: `${g.ip}: strict mode still ON but a disable is pending (${state}; ${rules}) - re-check in ~1 minute` };
    }
    return {
      level: "FAIL",
      summary: `${g.ip}: OVH game firewall STRICT MODE is ON (state ${state}; ${rules}) - all other UDP is dropped upstream`,
      remediation: strictModeRemediation(g.ip),
    };
  }
  if (g.firewallModeEnabled === null) {
    return { level: "WARN", summary: `${g.ip}: OVH game firewall mode could not be determined (state ${state})` };
  }
  if (stateLc !== "ok") {
    return {
      level: "WARN",
      summary: `${g.ip}: strict mode is off but OVH reports state ${state} (${rules}) - pending change; re-check in ~1 minute` +
        (stateLc.includes("enablepending") ? " (it is about to turn STRICT ON)" : ""),
    };
  }
  return { level: "PASS", summary: `${g.ip}: OVH game firewall strict mode off (state ok; ${rules})` };
}

export function networkFirewallVerdict(n: NetworkFirewall): Verdict {
  if (!n.exists) return { level: "PASS", summary: `${n.ip}: not on the OVH network firewall` };
  const deny = n.rules.filter((r) => r.action === "deny").length;
  const permit = n.rules.filter((r) => r.action === "permit").length;
  const rules = `${n.rules.length} rule(s) (${permit} permit, ${deny} deny)`;
  const state = n.state ?? "unknown";
  if (n.enabled === true) {
    return {
      level: "WARN",
      summary: `${n.ip}: OVH NETWORK firewall is ENABLED (state ${state}; ${rules}) - it can drop customer traffic upstream`,
      remediation:
        `Review with read-only GET /ip/${encodeURIComponent(n.ip)}/firewall/${encodeURIComponent(n.ip)}/rule (or OVH manager > IP > ${n.ip} > Firewall). ` +
        `Make sure the rules permit the ports customers use (TCP+UDP game ports, SSH forwards, 80/443, ICMP). ` +
        `Disabling or editing it is a production change that REQUIRES OWNER APPROVAL.`,
    };
  }
  if (n.enabled === null) return { level: "WARN", summary: `${n.ip}: OVH network firewall state could not be determined (${state})` };
  if (state.toLowerCase() !== "ok") return { level: "WARN", summary: `${n.ip}: network firewall disabled but OVH reports state ${state} - pending change` };
  return { level: "PASS", summary: `${n.ip}: OVH network firewall present but disabled (${rules})` };
}

export function worstLevel(levels: readonly Level[]): Level {
  return levels.includes("FAIL") ? "FAIL" : levels.includes("WARN") ? "WARN" : "PASS";
}

// ---------------------------------------------------------------------------
// GET-only HTTP layer
// ---------------------------------------------------------------------------

/** The only OVH entry point in this file. Method is hard-wired to GET. */
export type OvhGet = (path: string) => Promise<any>;
export const defaultOvhGet: OvhGet = (path) => ovh("GET", path);

const enc = encodeURIComponent;
const MAX_RULE_READS = 40;

/** Run `fn`; a 404 yields `null`, anything else propagates. */
async function orNull<T>(fn: () => Promise<T>): Promise<T | null> {
  try {
    return await fn();
  } catch (e: any) {
    if (e instanceof OvhHttpError ? e.status === 404 : /-> 404:/.test(String(e?.message))) return null;
    throw e;
  }
}

/**
 * Read one IP's game firewall. 404 (no game object) => `exists:false`. Any other
 * OVH/network error propagates so the caller can treat "could not read" separately
 * from "not enforced" (absence of evidence is never a PASS in the sweep).
 */
export async function getGameFirewall(ip: string, get: OvhGet = defaultOvhGet): Promise<GameFirewall> {
  const e = enc(ip);
  const game = await orNull(() => get(`/ip/${e}/game/${e}`));
  if (!game) return parseGameFirewall(ip, null);
  const ids = (await orNull(() => get(`/ip/${e}/game/${e}/rule`))) ?? [];
  const bodies: any[] = [];
  for (const id of (Array.isArray(ids) ? ids : []).slice(0, MAX_RULE_READS)) {
    const b = await orNull(() => get(`/ip/${e}/game/${e}/rule/${enc(String(id))}`));
    if (b) bodies.push({ id, ...b });
  }
  return parseGameFirewall(ip, game, bodies);
}

export async function getNetworkFirewall(ip: string, get: OvhGet = defaultOvhGet): Promise<NetworkFirewall> {
  const e = enc(ip);
  const list = await orNull(() => get(`/ip/${e}/firewall`));
  if (!Array.isArray(list) || !list.includes(ip)) return parseNetworkFirewall(ip, list, null);
  const detail = await orNull(() => get(`/ip/${e}/firewall/${e}`));
  const bodies: any[] = [];
  // Rules are only worth reading when the firewall is actually enforcing.
  if (detail?.enabled === true) {
    const seqs = (await orNull(() => get(`/ip/${e}/firewall/${e}/rule`))) ?? [];
    for (const seq of (Array.isArray(seqs) ? seqs : []).slice(0, MAX_RULE_READS)) {
      const b = await orNull(() => get(`/ip/${e}/firewall/${e}/rule/${enc(String(seq))}`));
      if (b) bodies.push({ sequence: seq, ...b });
    }
  }
  return parseNetworkFirewall(ip, list, detail, bodies);
}

/** Read both filters for one IP. Never throws: failure becomes `{ok:false,error}`. */
export async function checkIpFirewalls(ip: string, get: OvhGet = defaultOvhGet): Promise<IpFirewallReport> {
  try {
    const game = await getGameFirewall(ip, get);
    const network = await getNetworkFirewall(ip, get);
    return { ip, ok: true, game, network, gameVerdict: gameFirewallVerdict(game), networkVerdict: networkFirewallVerdict(network) };
  } catch (e: any) {
    return { ip, ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

// ---------------------------------------------------------------------------
// Per-node listing (DB-backed)
// ---------------------------------------------------------------------------

export type NodeFirewallEntry = {
  ip: string;
  source: "node" | "pool";
  /** DedicatedIp.status / purpose for pool rows. */
  poolStatus?: string;
  purpose?: string;
  report: IpFirewallReport;
};

export type NodeFirewallResult =
  | { applicable: false; reason: string; entries: [] }
  | { applicable: true; entries: NodeFirewallEntry[] };

/** The deduplicated IP list for a node: its public IP first, then every DedicatedIp row (any status/purpose). */
export function nodeIpTargets(
  node: { publicIp: string },
  pool: readonly { address: string; status?: string; purpose?: string }[]
): { ip: string; source: "node" | "pool"; poolStatus?: string; purpose?: string }[] {
  const out: { ip: string; source: "node" | "pool"; poolStatus?: string; purpose?: string }[] = [];
  const seen = new Set<string>();
  const add = (ip: string, rest: { source: "node" | "pool"; poolStatus?: string; purpose?: string }) => {
    const v = ip.trim();
    if (!v || seen.has(v)) return;
    seen.add(v);
    out.push({ ip: v, ...rest });
  };
  add(node.publicIp, { source: "node" });
  for (const p of pool) add(p.address, { source: "pool", poolStatus: p.status, purpose: p.purpose });
  return out;
}

/**
 * Check a node's own public IP and every DedicatedIp row on it (FREE and ASSIGNED,
 * any purpose). Non-OVH nodes (Hetzner) are not applicable. READ-ONLY toward OVH.
 * `nodeRef` is a Node.id or Node.name.
 */
export async function listGameFirewallForNode(nodeRef: string, get: OvhGet = defaultOvhGet): Promise<NodeFirewallResult> {
  const { db } = await import("./db"); // lazy: keep the pure parts importable without Prisma
  const node = await db.node.findFirst({ where: { OR: [{ id: nodeRef }, { name: nodeRef }] }, select: { id: true, provider: true, publicIp: true } });
  if (!node) throw new Error(`no Node matching '${nodeRef}'`);
  if (node.provider !== "OVH") return { applicable: false, reason: `provider is ${node.provider}, not OVH`, entries: [] };
  const pool = await db.dedicatedIp.findMany({ where: { nodeId: node.id }, select: { address: true, status: true, purpose: true }, orderBy: { address: "asc" } });
  return { applicable: true, entries: await checkTargets(nodeIpTargets(node, pool), get) };
}

/** Sequential on purpose (a handful of IPs; keeps us far under OVH rate limits). */
export async function checkTargets(
  targets: ReturnType<typeof nodeIpTargets>,
  get: OvhGet = defaultOvhGet
): Promise<NodeFirewallEntry[]> {
  const out: NodeFirewallEntry[] = [];
  for (const t of targets) out.push({ ...t, report: await checkIpFirewalls(t.ip, get) });
  return out;
}

