import type { DesiredAlert } from "./fleet-alert-plan";
import type { NodeFirewallEntry } from "./ovh-game-firewall";

export const OVH_GAME_FW_PREFIX = "OVH-GAME-FW:";
export const OVH_NET_FW_PREFIX = "OVH-NET-FW:";

export type NodeFirewallReading = { nodeId: string; nodeName: string; entries: readonly NodeFirewallEntry[] };

export function desiredOvhFirewallAlerts(readings: readonly NodeFirewallReading[]): { desired: DesiredAlert[]; readNodeIds: Set<string> } {
  const desired: DesiredAlert[] = [];
  const readNodeIds = new Set<string>();
  for (const n of readings) {
    if (n.entries.every((e) => e.report.ok)) readNodeIds.add(n.nodeId);
    for (const e of n.entries) {
      const r = e.report;
      if (!r.ok) continue;
      if (r.game.exists && r.game.firewallModeEnabled === true) {
        const carries = e.source === "node" || e.poolStatus === "ASSIGNED";
        desired.push({
          nodeId: n.nodeId,
          nodeName: n.nodeName,
          dimension: `${OVH_GAME_FW_PREFIX}${e.ip}`,
          severity: carries ? "CRITICAL" : "WARN",
          title: `OVH game firewall strict mode on ${e.ip}`,
          detail: `${n.nodeName} (${e.source === "node" ? "node public IP" : `pooled IP, ${e.poolStatus ?? "?"}`}). ${r.gameVerdict.summary}. ${r.gameVerdict.remediation ?? ""}`.trim(),
        });
      }
      if (r.network.exists && r.network.enabled === true) {
        desired.push({
          nodeId: n.nodeId,
          nodeName: n.nodeName,
          dimension: `${OVH_NET_FW_PREFIX}${e.ip}`,
          severity: "WARN",
          title: `OVH network firewall enabled on ${e.ip}`,
          detail: `${n.nodeName}. ${r.networkVerdict.summary}. ${r.networkVerdict.remediation ?? ""}`.trim(),
        });
      }
    }
  }
  return { desired, readNodeIds };
}
