/**
 * OVH upstream-firewall sweep (hourly). READ-ONLY toward OVH (GET only).
 *
 * For every enabled OVH node: read the node's public IP and every DedicatedIp row
 * on it, raise a debounced, auto-resolving admin alert (via lib/fleet-alert-plan.ts,
 * dimension prefixes OVH-GAME-FW: / OVH-NET-FW:) when
 *   - the game firewall is in STRICT mode (OVH drops all UDP not on a rule), or
 *   - the network firewall is enabled (WARN).
 * Incident: 2026-10-04, node-4 strict mode silently black-holed every UDP game.
 *
 * Default ON (it only reads); turn off with Setting `ovh_game_firewall_check_enabled` = false.
 * Failure-silent: an OVH outage / slow API logs and returns; it can never throw into
 * or stall the sweep runner (hard overall deadline below).
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { getSettingBool } from "../lib/settings";
import { ovhConfigured } from "../lib/ovh";
import { planFleetAlerts } from "../lib/fleet-alert-plan";
import { checkTargets, nodeIpTargets } from "../lib/ovh-game-firewall";
import { desiredOvhFirewallAlerts, type NodeFirewallReading } from "../lib/ovh-firewall-alert-plan";
import { applyFleetAlerts, openFleetAlerts } from "./fleet-alerts";

export const OVH_FW_SWEEP_DEADLINE_MS = 5 * 60_000;
export const OVH_FW_SETTING = "ovh_game_firewall_check_enabled";

export async function ovhGameFirewallSweep(): Promise<void> {
  if (SANDBOX || !ovhConfigured()) return;
  try {
    if (!(await getSettingBool(OVH_FW_SETTING, true))) return;
    const work = runSweep();
    // Hard deadline: if OVH hangs we stop waiting (the pending fetches have their own 30 s timeouts).
    let timer: NodeJS.Timeout | undefined;
    const deadline = new Promise<"timeout">((res) => { timer = setTimeout(() => res("timeout"), OVH_FW_SWEEP_DEADLINE_MS); });
    const r = await Promise.race([work.then(() => "done" as const), deadline]);
    if (timer) clearTimeout(timer);
    if (r === "timeout") console.error("[ovh-fw] sweep exceeded its deadline; skipped this round");
  } catch (e) {
    console.error("[ovh-fw] sweep failed (ignored)", e instanceof Error ? e.message : e);
  }
}

async function runSweep(): Promise<void> {
  const nodes = await db.node.findMany({
    where: { enabled: true, provider: "OVH" },
    select: { id: true, name: true, publicIp: true, dedicatedIps: { select: { address: true, status: true, purpose: true } } },
  });
  const readings: NodeFirewallReading[] = [];
  for (const n of nodes) {
    const entries = await checkTargets(nodeIpTargets(n, n.dedicatedIps.map((d) => ({ address: d.address, status: d.status, purpose: d.purpose }))));
    readings.push({ nodeId: n.id, nodeName: n.name, entries });
    for (const e of entries) {
      if (!e.report.ok) console.error(`[ovh-fw] ${n.name} ${e.ip}: could not read (${e.report.error})`);
      else if (e.report.gameVerdict.level === "FAIL") console.error(`[ovh-fw] ${n.name}: ${e.report.gameVerdict.summary}`);
    }
  }
  const { desired, readNodeIds } = desiredOvhFirewallAlerts(readings);
  const all = await openFleetAlerts();
  const ops = planFleetAlerts({
    desired,
    open: all,
    readNodeIds,
    nodeNames: new Map(nodes.map((n) => [n.id, n.name])),
    now: new Date(),
  });
  await applyFleetAlerts(ops);
}
EOF
