/**
 * READ-ONLY check of OVH's upstream filters (game firewall strict mode + network
 * firewall) for a node's public IP and every pooled DedicatedIp on it. GET only.
 *
 *   npx tsx scripts/ovh-game-firewall-check.ts --node node-5        # by Node.name / id / public IP
 *   npx tsx scripts/ovh-game-firewall-check.ts --all
 *   npx tsx scripts/ovh-game-firewall-check.ts --ip 139.99.125.21   # one IP, no DB needed
 *   add --json for machine output, --verify for verify-node.sh's record format
 *
 * Exit: 0 no FAIL, 1 a FAIL (strict mode on), 2 could not run (no creds, usage, error).
 * Incident background: docs/DOCUMENTATION.md > "OVH game firewall guard".
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { checkIpFirewalls, checkTargets, nodeIpTargets, worstLevel, type Level, type NodeFirewallEntry } from "../lib/ovh-game-firewall";

// Scripts are not started by Next, so load the few vars we need from .env if the shell did not export them.
for (const f of [path.resolve(__dirname, "../.env"), "/opt/nxeon/.env"]) {
  try {
    for (const line of readFileSync(f, "utf8").split("\n")) {
      const m = /^(OVH_[A-Z_]+|DATABASE_URL)=(.*)$/.exec(line.trim());
      if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
    }
    break;
  } catch {}
}

const US = "\x1f";
const args = process.argv.slice(2);
const flag = (n: string) => args.includes(n);
const opt = (n: string) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };

function rollup(entries: NodeFirewallEntry[]): { level: Level; msg: string; fix: string } {
  const levels: Level[] = [];
  const bad: string[] = [];
  let fix = "";
  let unread = 0;
  for (const e of entries) {
    if (!e.report.ok) { unread++; levels.push("WARN"); bad.push(`${e.ip}: could not read (${e.report.error})`); continue; }
    for (const v of [e.report.gameVerdict, e.report.networkVerdict]) {
      levels.push(v.level);
      if (v.level !== "PASS") { bad.push(v.summary); if (!fix && v.remediation) fix = v.remediation; }
    }
  }
  const level = worstLevel(levels);
  if (level === "PASS") return { level, msg: `OVH game firewall strict mode off / not enforced, network firewall not blocking, on ${entries.length} IP(s): ${entries.map((e) => e.ip).join(", ")}`, fix };
  return { level, msg: bad.join(" | ") + (unread ? " (OVH unreadable for some IPs: absent evidence is not a PASS)" : ""), fix };
}

async function main() {
  const { ovhConfigured } = await import("../lib/ovh");
  const verify = flag("--verify");
  if (!ovhConfigured()) {
    const m = "SKIPPED (no OVH creds in this environment - run from the primary, which holds OVH_APPLICATION_KEY/SECRET/CONSUMER_KEY)";
    console.log(verify ? ["RESULT", "WARN", "net.ovh_game_firewall", m, "run scripts/verify-node.sh from the primary, or check the panel manually: OVH manager > IP > <ip> > Game firewall"].join(US) : m);
    process.exit(verify ? 0 : 2);
  }

  let groups: { name: string; entries: NodeFirewallEntry[] }[] = [];
  const ipArg = opt("--ip");
  if (ipArg) {
    groups = [{ name: ipArg, entries: [{ ip: ipArg, source: "node", report: await checkIpFirewalls(ipArg) }] }];
  } else {
    const { db } = await import("../lib/db");
    const nodeArg = opt("--node");
    if (!nodeArg && !flag("--all")) { console.error("usage: ovh-game-firewall-check.ts (--node <name|id|ip> | --all | --ip <ip>) [--json] [--verify]"); process.exit(2); }
    const nodes = await db.node.findMany({
      where: nodeArg ? { OR: [{ id: nodeArg }, { name: nodeArg }, { publicIp: nodeArg }] } : { provider: "OVH" },
      select: { name: true, provider: true, publicIp: true, dedicatedIps: { select: { address: true, status: true, purpose: true } } },
      orderBy: { createdAt: "asc" },
    });
    if (!nodes.length) { console.error(`no Node matches '${nodeArg}'`); process.exit(2); }
    for (const n of nodes) {
      if (n.provider !== "OVH") {
        const m = `SKIPPED (not an OVH node: provider ${n.provider})`;
        if (verify) { console.log(["RESULT", "PASS", "net.ovh_game_firewall", m, ""].join(US)); continue; }
        console.log(`${n.name}: ${m}`); continue;
      }
      groups.push({ name: n.name, entries: await checkTargets(nodeIpTargets(n, n.dedicatedIps.map((d) => ({ address: d.address, status: d.status, purpose: d.purpose })))) });
    }
    await db.$disconnect();
  }

  let worst: Level = "PASS";
  for (const g of groups) {
    const r = rollup(g.entries);
    worst = worstLevel([worst, r.level]);
    if (verify) console.log(["RESULT", r.level, "net.ovh_game_firewall", r.msg, r.fix].join(US));
    else if (flag("--json")) console.log(JSON.stringify({ node: g.name, level: r.level, entries: g.entries }, null, 2));
    else {
      console.log(`== ${g.name}: ${r.level}`);
      for (const e of g.entries) {
        const tag = `${e.source}${e.poolStatus ? `/${e.poolStatus}` : ""}${e.purpose ? `/${e.purpose}` : ""}`;
        if (!e.report.ok) { console.log(`  [WARN] ${e.ip} (${tag}) unreadable: ${e.report.error}`); continue; }
        console.log(`  [${e.report.gameVerdict.level}] ${e.report.gameVerdict.summary}   (${tag})`);
        if (e.report.networkVerdict.level !== "PASS" || e.report.network.exists) console.log(`  [${e.report.networkVerdict.level}] ${e.report.networkVerdict.summary}`);
      }
      if (r.fix) console.log(`  fix: ${r.fix}`);
    }
  }
  process.exit(verify ? 0 : worst === "FAIL" ? 1 : 0);
}

main().catch((e) => { console.error(e instanceof Error ? e.message : e); process.exit(2); });
EOF
