import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  parseGameFirewall, parseNetworkFirewall, gameFirewallVerdict, networkFirewallVerdict, strictModeRemediation,
  getGameFirewall, getNetworkFirewall, checkIpFirewalls, checkTargets, nodeIpTargets, worstLevel, describeGameRule, type OvhGet,
} from "../lib/ovh-game-firewall.ts";
