const notFound = (path: string) => new OvhHttpError(`OVH GET ${path} -> 404: This service does not exist`, 404);

function fakeOvh(table: Record<string, unknown>, calls: string[] = []): OvhGet {
  return async (path) => {
    calls.push(path);
    if (path in table) {
      const v = table[path];
      if (v instanceof Error) throw v;
      return v;
    }
    throw notFound(path);
  };
}

