test("alert: debounced, then auto-resolves when strict mode is turned off", async () => {
  const strict = desiredOvhFirewallAlerts([await reading("n4", "node-4", [{ ip: "15.235.171.191", source: "pool", poolStatus: "ASSIGNED", strict: true }])]);
  const names = new Map([["n4", "node-4"]]);
  // first sighting: create + notify
  let ops = planFleetAlerts({ desired: strict.desired, open: [], readNodeIds: strict.readNodeIds, nodeNames: names, now: NOW });
  assert.equal(ops.length, 1);
  assert.equal(ops[0].op, "create");
  // 1 hour later, same condition, notified 1h ago: silent refresh (debounce)
  const open = [{ id: "a1", nodeId: "n4", dimension: "OVH-GAME-FW:15.235.171.191", severity: "CRITICAL", lastNotifiedAt: NOW }];
  ops = planFleetAlerts({ desired: strict.desired, open, readNodeIds: strict.readNodeIds, nodeNames: names, now: new Date(NOW.getTime() + 3_600_000) });
  assert.equal(ops.length, 1);
  assert.equal(ops[0].op, "update");
  assert.equal((ops[0] as any).notifyNow, false);
  // owner disables strict mode: node read OK, no desired alert => resolve
  const off = desiredOvhFirewallAlerts([await reading("n4", "node-4", [{ ip: "15.235.171.191", source: "pool", poolStatus: "ASSIGNED", strict: false }])]);
  ops = planFleetAlerts({ desired: off.desired, open, readNodeIds: off.readNodeIds, nodeNames: names, now: NOW });
  assert.equal(ops.length, 1);
  assert.equal(ops[0].op, "resolve");
});

