      if (p === `/ip/${s.ip}/game/${s.ip}`) return { ipOnGame: s.ip, state: "ok", firewallModeEnabled: !!s.strict, maxRules: 30 };
      if (p === `/ip/${s.ip}/game/${s.ip}/rule`) return [];
      if (p === `/ip/${s.ip}/firewall`) return s.netOn ? [s.ip] : [];
      if (p === `/ip/${s.ip}/firewall/${s.ip}`) return { ipOnFirewall: s.ip, state: "ok", enabled: true };
      if (p === `/ip/${s.ip}/firewall/${s.ip}/rule`) return [];
      throw notFound(p);
    };
    entries.push({ ip: s.ip, source: s.source, poolStatus: s.poolStatus, report: await checkIpFirewalls(s.ip, get) });
  }
  return { nodeId, nodeName, entries };
}

const NOW = new Date("2026-10-06T12:00:00Z");

test("alert: strict IP raises CRITICAL (node IP / ASSIGNED) or WARN (FREE pool), titled per spec", async () => {
  const r = await reading("n4", "node-4", [
    { ip: "139.99.125.21", source: "node", strict: true },
    { ip: "15.235.171.191", source: "pool", poolStatus: "ASSIGNED", strict: true },
    { ip: "15.235.105.21", source: "pool", poolStatus: "FREE", strict: true },
    { ip: "15.235.171.117", source: "pool", poolStatus: "ASSIGNED", strict: false },
  ]);
  const { desired, readNodeIds } = desiredOvhFirewallAlerts([r]);
  assert.equal(desired.length, 3);
  assert.deepEqual(desired.map((d) => d.severity), ["CRITICAL", "CRITICAL", "WARN"]);
  assert.equal(desired[0].title, "OVH game firewall strict mode on 139.99.125.21");
  assert.equal(desired[0].dimension, "OVH-GAME-FW:139.99.125.21");
  assert.ok(readNodeIds.has("n4"));
  assert.ok(desired.every((d) => isFleetDimension(d.dimension)));
});

test("alert: network firewall enabled => WARN OVH-NET-FW", async () => {
