  ])]);
  assert.equal(bad.desired.length, 0);
  assert.equal(bad.readNodeIds.size, 0);
  const open = [{ id: "a1", nodeId: "n4", dimension: "OVH-GAME-FW:15.235.171.191", severity: "CRITICAL", lastNotifiedAt: NOW }];
  const ops = planFleetAlerts({ desired: bad.desired, open, readNodeIds: bad.readNodeIds, nodeNames: new Map([["n4", "node-4"]]), now: NOW });
  assert.equal(ops.length, 0);
});
